	};
	function sampleCascadeArray(shadowMap:Sampler2DArray, layer:Int, shadowPos:Vec3, bias:Float, pcfScale:Float, esmPower:Float, worldPos:Vec3, samplingMode:Int):Float {
		var zMax = shadowPos.z.saturate();
