{
	var boneMatrixX:Mat3x4;
	var boneMatrixY:Mat3x4;
	var boneMatrixZ:Mat3x4;
	var boneMatrixW:Mat3x4;
	var skinWeights:Vec4;
	function applySkinPoint(p:Vec3):Vec3 {
		var transformed = (p * boneMatrixX) * skinWeights.x + (p * boneMatrixY) * skinWeights.y + (p * boneMatrixZ) * skinWeights.z;
		if (skinWeights.w > 0.0) transformed += (p * boneMatrixW) * skinWeights.w;
		return transformed;
	};
	function applySkinVec(v:Vec3):Vec3 {
		var transformed = (v * mat3(boneMatrixX)) * skinWeights.x + (v * mat3(boneMatrixY)) * skinWeights.y + (v * mat3(boneMatrixZ)) * skinWeights.z;
		if (skinWeights.w > 0.0) transformed += (v * mat3(boneMatrixW)) * skinWeights.w;
		return transformed;
	};
}

