	@param var capsuleSlot:Int;
	@param var rectSlot:Int;
	var aabbMin:Vec3;
	var aabbMax:Vec3;
	var count:Int;
	var typeCount:Int;
	var base:Int;
	function unproject(ndc:Vec2, z:Float):Vec3 {
		var p = vec4(ndc, z, 1.0) * camera.invProj;
		return p.xyz / p.w;
